 form:[['<b>Youth centre – practical information</b>','',null],['Open to','young people aged 13 to {6}',6],['Membership','{7} dong per year',7],['To join, bring','a photo and your student {8}',8],['Volunteers needed for','{9} programme for younger children',9],['Opening event','a {10} competition on Saturday',10]],
